-- Batch 01: reproducible geospatial distances from existing coordinate snapshot; no assertion of walking access.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261125_v6';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; source_row jsonb; sub_batch int:=1; expected_before int:=0; expected_added int:=25;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261125_v6_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v6_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 -- Serialize the brief data transaction against other writes, not normal reads.
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($spec$[{"id":"03f94714-fd1a-429f-abba-21c931f41026","bid":"ba4214ac-d323-4cae-a808-e8fc6eb090b7","station":"朝阳门","station_id":"BV10004298","line":"地铁2号线","slng":116.434508,"slat":39.924487,"meters":700},{"id":"06c23ea0-a545-446c-84da-75dccb99a231","bid":"5f024b40-14a2-493e-a0d9-43492b5f8ddf","station":"建国门","station_id":"BV10013432","line":"地铁1号线八通线","slng":116.434648,"slat":39.908555,"meters":500},{"id":"1669ffe8-f07c-44da-882b-b359b18fa155","bid":"5123584c-475a-49a3-8519-972d12ef93df","station":"东四十条","station_id":"BV10001047","line":"地铁2号线","slng":116.434137,"slat":39.933704,"meters":400},{"id":"2159ec01-7b8a-42fb-9262-167076687a03","bid":"995fc48c-a100-4ee3-aed6-4271e7236d1b","station":"国贸","station_id":"BV10013461","line":"地铁10号线","slng":116.461841,"slat":39.909104,"meters":200},{"id":"3bbbbbb2-600d-481b-b328-daf72a31b122","bid":"080387f0-d658-4681-8bf8-68a818fe3636","station":"魏公村","station_id":"BV10000255","line":"地铁4号线大兴线","slng":116.32322,"slat":39.957904,"meters":400},{"id":"44ce3e58-a78d-488f-98eb-3bd0ee0b6117","bid":"018f6bcc-7a11-4494-bd54-2511563ea772","station":"国贸","station_id":"BV10013461","line":"地铁1号线八通线","slng":116.459707,"slat":39.908421,"meters":200},{"id":"53203ff0-49c6-4714-987b-836ccbea2ce1","bid":"f097e6a7-37d9-4a46-8094-557020a37f86","station":"阜成门","station_id":"BV10001036","line":"地铁2号线","slng":116.356215,"slat":39.923677,"meters":600},{"id":"5a7300c1-42b8-4456-bd91-fc1faec3080b","bid":"2b119df5-3bfb-4591-ac16-2a129d95fd64","station":"车公庄","station_id":"BV10013437","line":"地铁6号线","slng":116.354357,"slat":39.932397,"meters":500},{"id":"5dafee8a-3a5b-42a4-bc06-7c8372439a6c","bid":"59dd5fbb-990f-4efb-8cfc-d417d688c202","station":"古城","station_id":"BV10000295","line":"地铁1号线八通线","slng":116.190337,"slat":39.90745,"meters":800},{"id":"60afaf1e-b592-41a3-9508-33edfd24d836","bid":"7852d43e-dce4-49d0-945f-f92505ede844","station":"魏公村","station_id":"BV10000255","line":"地铁4号线大兴线","slng":116.32322,"slat":39.957904,"meters":300},{"id":"8667fbea-949e-46c2-a822-9582ec3211a8","bid":"a55ff45e-79e0-41c1-83ec-3c7ca7f19d93","station":"复兴门","station_id":"BV10007375","line":"地铁1号线八通线","slng":116.357793,"slat":39.907174,"meters":400},{"id":"8891b56f-35c0-4be6-ad9a-283bb9f0cb88","bid":"318735b6-d1fa-4918-ae4d-4fb265e23327","station":"建国门","station_id":"BV10013432","line":"地铁1号线八通线","slng":116.434648,"slat":39.908555,"meters":700},{"id":"90c8b8cc-980e-4392-ba3f-78e8676bfb4a","bid":"1db956ef-3671-4764-bd8b-dffc84bea606","station":"荣京东街","station_id":"BV10003511","line":"地铁亦庄线","slng":116.51339,"slat":39.793132,"meters":700},{"id":"9598992d-d00e-40d0-b9aa-9311d4e85411","bid":"365a9f79-2d97-4090-93b6-bd4bf8d55f29","station":"国贸","station_id":"BV10013461","line":"地铁10号线","slng":116.461841,"slat":39.909104,"meters":400},{"id":"9dc05df8-7fb1-40cb-9ccc-7c5d60aa3156","bid":"5a611cb7-3245-4930-8e8a-cda60cdb44bb","station":"东湖渠","station_id":"BV10416590","line":"地铁14号线","slng":116.467415,"slat":40.010566,"meters":700},{"id":"a463babd-661e-4caf-98ba-730b67c162c4","bid":"6bb2efa3-1af8-4a28-8d9d-01e2393ed9c6","station":"丽泽商务区","station_id":"BV10013372","line":"地铁14号线","slng":116.331582,"slat":39.867988,"meters":300},{"id":"a694de38-87cc-4892-b492-25541113fa38","bid":"8b7ee586-566a-418c-8fe4-985de7f55242","station":"国贸","station_id":"BV10013461","line":"地铁10号线","slng":116.461841,"slat":39.909104,"meters":700},{"id":"aa032edf-2f87-4fd0-b7ef-0e2f4cad0dd9","bid":"05cfab5f-70a0-411c-98f7-4953edf42606","station":"东大桥","station_id":"BV10000548","line":"地铁17号线","slng":116.450379,"slat":39.922852,"meters":200},{"id":"c1a6c1e0-bd00-47a3-a68e-3bf12d332921","bid":"1439a0a2-4b65-4883-828d-70606753d30a","station":"国贸","station_id":"BV10013461","line":"地铁10号线","slng":116.461841,"slat":39.909104,"meters":400},{"id":"c211dcae-573f-4bf5-98eb-6259593c9439","bid":"420377ac-0e7e-4817-91fa-7897a40356c9","station":"高家园","station_id":"BV10416589","line":"地铁14号线","slng":116.488543,"slat":39.980572,"meters":600},{"id":"d397cf94-54d0-4c95-b087-f812fb60e06a","bid":"b6d237b7-ad08-4cee-80af-86fae66a470c","station":"将台","station_id":"BV10416595","line":"地铁14号线","slng":116.490213,"slat":39.971026,"meters":700},{"id":"d44ecfa2-5b42-42cc-8472-94528ccf1fb4","bid":"dbaec222-e084-4427-a889-852e725850a7","station":"复兴门","station_id":"BV10007375","line":"地铁1号线八通线","slng":116.357793,"slat":39.907174,"meters":700},{"id":"d7831ad4-15da-4715-9964-2f7b421c456c","bid":"915527c5-0e4e-4835-bbc2-1441ad1e31bf","station":"望京东","station_id":"BV10013402","line":"地铁15号线","slng":116.487032,"slat":40.003176,"meters":500},{"id":"f4bfd071-789f-4c42-b06d-afb5663fc55f","bid":"7e8cf4bc-f982-4528-94c9-ec26a577832a","station":"纪家庙","station_id":"BV10006086","line":"地铁10号线","slng":116.333381,"slat":39.844433,"meters":700},{"id":"fd725dbc-703d-4fec-90b5-86a08b180d17","bid":"877e2902-1023-4fb8-bd74-651a46c53e27","station":"亮马桥","station_id":"BV10000196","line":"地铁10号线","slng":116.462156,"slat":39.949381,"meters":600}]$spec$::jsonb) v(id uuid,bid uuid,station text,station_id text,line text,slng double precision,slat double precision,meters int)), c AS (SELECT b.id bid,b.name,d.id target_id,'metro_access' field_name,to_jsonb('据2026-04-03地图快照，楼宇标注点至'||v.line||v.station||'站中心直线约'||v.meters||'米（非步行距离）') new_value,'text' value_type,'buildings' source_table,b.id source_id,'location_lng,location_lat' source_field,'internal_geospatial_calculation' source_kind,'m (rounded to 100m)' unit,'原地图站点快照 public/data/beijing_map_data.json; blob_sha=865e84fee5ae5cf088e30228ab8a2e1501304734; generatedAt=2026-04-03T05:39:01.612Z; station_id='||v.station_id||'; line='||v.line||'; station='||v.station||'; station_coordinates='||v.slng||','||v.slat||'; building_coordinates='||b.location_lng||','||b.location_lat||'; great-circle calculation R=6371000m; not a walking distance, station entrance or current access survey' note FROM specs v JOIN public.buildings b ON b.id=v.bid JOIN public.building_brochure_data d ON d.id=v.id AND d.building_id=b.id WHERE b.is_active AND b.city IN ('北京','北京市') AND b.project_type='stock' AND b.tracking_scope='tracked' AND b.merged_into_id IS NULL AND d.metro_access IS NULL AND b.location_lng BETWEEN 115 AND 118 AND b.location_lat BETWEEN 39 AND 41 AND nullif(trim(d.address),'') IS NOT NULL AND (SELECT count(*) FROM public.building_brochure_data y WHERE y.building_id=b.id)=1 AND round((6371000*2*asin(sqrt(least(1.0,power(sin(radians(v.slat-b.location_lat)/2),2)+cos(radians(b.location_lat))*cos(radians(v.slat))*power(sin(radians(v.slng-b.location_lng)/2),2))))/100.0)::numeric)*100=v.meters AND v.meters BETWEEN 100 AND 800) SELECT c.* FROM c WHERE NOT EXISTS(SELECT 1 FROM public.building_data_field_provenance p WHERE p.building_id=c.bid AND p.target_table='building_brochure_data' AND p.field_name=c.field_name) AND NOT EXISTS(SELECT 1 FROM public.audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=c.target_id::text AND (a.details->>'field_name'=c.field_name OR a.new_values ? c.field_name)) ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  VALUES(r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,'other','legacy_unknown','系统地图坐标与已归档地铁站快照计算',now_ts,now_ts,'legacy_backfill',ev,'batch_ref=ai_building_field_backfill_20261125_v6_100; source_table='||r.source_table||'; source_record_id='||r.source_id||'; source_field='||r.source_field||'; unit='||r.unit||'; '||r.note||'; AI-assisted',true);
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261125_v6_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_table',r.source_table,'source_record_id',r.source_id,'source_field',r.source_field,'source_kind',r.source_kind,'unit',r.unit,'verification_status','legacy_backfill','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR NOT EXISTS(SELECT 1 FROM public.building_data_field_provenance p JOIN public.audit_logs a ON a.event_id='ai_field_fill:'||ev::text WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value AND a.new_values->r.field_name=p.field_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected % qualifying fields, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v6_100';
COMMIT;